//                            0, dN_i/dy, 0;
//                            0, 0, dN_i/dz;
//                            dN_i/dy, dN_i/dx, 0;
//                            dN_i/dz, 0, dN_i/dx;
//                            0, dN_i/dz, dN_i/dy]
std::vector<Eigen::Matrix<double,6,3>> computeC(const Eigen::Matrix4d& H) {
    std::vector<Eigen::Matrix<double,6,3>> C(4);

    for (int i = 0; i < 4; ++i) {
        C[i] = Eigen::Matrix<double,6,3>::Zero();
        // H.row(i) = [1, x_i, y_i, z_i], so dN_i/dx = H_inv(0,1), etc.
        // But here H is [1 x y z] for each node => H_inv gives coefficients for N_i = H_inv_row_i * [1 x y z]
        // So dN_i/dx = H_inv(i,1), dN_i/dy = H_inv(i,2), dN_i/dz = H_inv(i,3)
        // We'll compute C after H_inv is available — but for now, placeholder.
        // Actually: in ktetra, we’ll compute H_inv first, then compute dN/dx etc. from it.
        // So this function should NOT use H directly — we’ll refactor: compute C *after* H_inv.
        // So leave C uninitialized here; will fill in ktetra.
    }

    return C;
}

// Helper function to compute transformation matrix T for node i (identity for now)
Eigen::Matrix3d computeT(int /*node_idx*/) {
