}

// Main KSOLID subroutine equivalent
void ksolid(int itype, std::vector<double>& ecpt, Eigen::MatrixXd& stiffness_matrix,
            double E, double nu, const std::vector<std::vector<double>>& node_coords) {
    // For wedge element (ITYPE = 1), we use the first 12 tetrahedrons from the mapping matrix
    std::vector<std::vector<int>> wedge_mapping = {
        {1,2,3,4}, {1,2,3,5}, {1,2,3,6}, {1,4,5,6},
        {2,4,5,6}, {3,4,5,6}, {2,1,4,6}, {2,3,4,6},
        {1,3,4,5}, {2,3,4,5}, {3,1,5,6}, {2,1,5,6}
    };

    // Reset stiffness matrix
    stiffness_matrix.setZero();

    // Process each tetrahedron in the wedge decomposition
    for (int i = 0; i < static_cast<int>(wedge_mapping.size()); ++i) {
        // Create ECPT for this tetrahedron
        std::vector<double> tet_ecpt(100, 0.0);

        // Copy element ID and material ID
        tet_ecpt[0] = ecpt[0];  // Element ID
        tet_ecpt[1] = ecpt[1];  // Material ID

        // Copy grid point IDs (1-based indexing in Fortran, 0-based here)
        for (int j = 0; j < 4; ++j) {
            tet_ecpt[2+j] = static_cast<double>(wedge_mapping[i][j]);
        }

        // Copy coordinates for each grid point
        for (int j = 0; j < 4; ++j) {
            int node_idx = wedge_mapping[i][j] - 1; // Convert to 0-based
            if (node_idx >= 0 && node_idx < static_cast<int>(node_coords.size())) {
                tet_ecpt[7 + 4*j] = node_coords[node_idx][0]; // X
                tet_ecpt[8 + 4*j] = node_coords[node_idx][1]; // Y
                tet_ecpt[9 + 4*j] = node_coords[node_idx][2]; // Z
            }
        }

        // Set element temperature (assume 0 for this test)
        tet_ecpt[22] = 0.0;

        // Call ktetra for this tetrahedron
        int iopt = i + 1;
        ktetra(iopt, 1, tet_ecpt, stiffness_matrix, E, nu, node_coords);
    }
}

// KTETRA subroutine equivalent
void ktetra(int iopt, int jtype, std::vector<double>& ecpt, Eigen::MatrixXd& stiffness_matrix,
            double E, double nu, const std::vector<std::vector<double>>& node_coords) {
    // Extract the 4 global node IDs (1-based) from ecpt[2..5]
    std::vector<int> tet_nodes(4);
    for (int i = 0; i < 4; ++i) {
        tet_nodes[i] = static_cast<int>(ecpt[2+i]);
    }

    // Build H matrix (4x4): [1, x, y, z] for each node
    Eigen::Matrix4d H;
    H.setZero();
    for (int i = 0; i < 4; ++i) {
        int node_idx = tet_nodes[i] - 1;
        if (node_idx < 0 || node_idx >= static_cast<int>(node_coords.size())) {
            return;
        }
        H(i,0) = 1.0;
        H(i,1) = node_coords[node_idx][0];
        H(i,2) = node_coords[node_idx][1];
        H(i,3) = node_coords[node_idx][2];
    }

    // Invert H matrix
    Eigen::Matrix4d H_inv;
    double h_deter;
    if (!invert4x4(H, H_inv, h_deter)) {
        return; // Bad geometry
    }
    h_deter = std::abs(h_deter);

    // Compute material matrix G
    Matrix6d G = computeG(E, nu);

    // Compute C matrices: C[i] is 6x3, where row k = derivative of strain component k w.r.t. u,v,w
    // dN_i/dx = H_inv(i,1), dN_i/dy = H_inv(i,2), dN_i/dz = H_inv(i,3)
    std::vector<Eigen::Matrix<double,6,3>> C(4);
    for (int i = 0; i < 4; ++i) {
        C[i] = Eigen::Matrix<double,6,3>::Zero();
        double dNdx = H_inv(i,1);
        double dNdy = H_inv(i,2);
        double dNdz = H_inv(i,3);

        C[i](0,0) = dNdx; // εxx
        C[i](1,1) = dNdy; // εyy
        C[i](2,2) = dNdz; // εzz
        C[i](3,0) = dNdy; C[i](3,1) = dNdx; // γxy
        C[i](4,0) = dNdz; C[i](4,2) = dNdx; // γxz
        C[i](5,1) = dNdz; C[i](5,2) = dNdy; // γyz
    }

    // Compute full 12x12 tet stiffness matrix K_tet
    Eigen::Matrix<double,12,12> K_tet = Eigen::Matrix<double,12,12>::Zero();

    // Loop over all node pairs (i,j) = 0..3
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            // Compute 3x3 block: C[i]^T * G * C[j]
            Eigen::Matrix3d K_block = C[i].transpose() * G * C[j];

            // Apply nodal transformations: T_i^T * K_block * T_j
            Eigen::Matrix3d T_i = computeT(tet_nodes[i]);
            Eigen::Matrix3d T_j = computeT(tet_nodes[j]);
            K_block = T_i.transpose() * K_block * T_j;

            // Place into K_tet at (3*i : 3*i+2, 3*j : 3*j+2)
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    K_tet(3*i + r, 3*j + c) += K_block(r,c);
                }
            }
        }
    }

    // Apply scale factor: for linear tet, ∫ dV = |det(H)| / 6
    double scale_factor = h_deter / 6.0;
    if (jtype == 1) { // wedge
        if (iopt <= 6) {
            scale_factor *= 2.0; // first 6 tets weighted double
        }
    }
    K_tet *= scale_factor;

    // Assemble into global stiffness matrix (18x18)
    for (int i = 0; i < 4; ++i) {
        int global_node_i = tet_nodes[i] - 1; // 0-based global node index
        if (global_node_i < 0 || global_node_i >= 6) continue;
        int base_i = 3 * global_node_i;

        for (int j = 0; j < 4; ++j) {
            int global_node_j = tet_nodes[j] - 1;
            if (global_node_j < 0 || global_node_j >= 6) continue;
            int base_j = 3 * global_node_j;

            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    stiffness_matrix(base_i + r, base_j + c) += K_tet(3*i + r, 3*j + c);
                }
            }
        }
    }
}

